  const PRODUCT_IMAGES = {};

  function buildImgArea(pid, p, sizeClass){
    const real = PRODUCT_IMAGES[pid];
    const icon = CATEGORY_ICONS[p.category] || '';
    if(real){
      return '<img src="'+real+'" alt="'+p.name+'" loading="lazy" style="width:100%;height:100%;object-fit:contain;" onerror="this.outerHTML=\''+icon.replace(/'/g,"\\'")+'\';">';
    }
    return icon;
  }

  function renderProductCardImages(){
    document.querySelectorAll('.prod-card[data-pid]').forEach(function(card){
      const pid = card.getAttribute('data-pid');
      const p = PRODUCT_DB[pid];
      if(!p) return;
      const div = document.createElement('div');
      div.className = 'prod-img';
      div.innerHTML = buildImgArea(pid, p);
      card.insertBefore(div, card.firstChild);
    });
  }
  document.addEventListener('DOMContentLoaded', renderProductCardImages);

  function stockColor(stock){
    if(stock === 0) return {color:"#e24b4a",bg:"#fcebeb"};
    if(stock <= 1) return {color:"#993c1d",bg:"#faece7"};
    if(stock <= 3) return {color:"#854f0b",bg:"#faeeda"};
    return {color:"#3b6d11",bg:"#eaf3de"};
  }

  function openProductModal(pid){
    const p = PRODUCT_DB[pid];
    if(!p) return;
    document.getElementById('modalTag').textContent = p.category;
    document.getElementById('modalTitle').textContent = p.name;
    document.getElementById('modalImg').innerHTML = buildImgArea(pid, p);

    const sc = stockColor(p.stock);
    const stockEl = document.getElementById('modalStock');
    stockEl.textContent = p.stockLabel;
    stockEl.style.color = sc.color;
    stockEl.style.background = sc.bg;

    const specsEl = document.getElementById('modalSpecs');
    specsEl.innerHTML = '';
    for(const [k,v] of Object.entries(p.specs)){
      const row = document.createElement('div');
      row.className = 'modal-spec-row';
      row.innerHTML = '<span class="k">'+k+'</span><span class="v">'+v+'</span>';
      specsEl.appendChild(row);
    }

    const noteEl = document.getElementById('modalGenericNote');
    if(p.generic){
      noteEl.innerHTML = '<div class="modal-generic-note">Spesifikasi detail untuk model ini belum tersedia di sistem kami. Hubungi tim kami untuk info lengkap kapasitas dan fitur.</div>';
    } else {
      noteEl.innerHTML = '';
    }

    const waBtn = document.getElementById('modalWaBtn');
    if(p.stock > 0){
      const text = encodeURIComponent('Halo, saya tertarik dengan '+p.name+' ('+p.category+'). Apakah masih tersedia?');
      waBtn.disabled = false;
      waBtn.onclick = ()=> window.open('https://wa.me/6285111219445?text='+text, '_blank');
      waBtn.querySelector('svg').style.display = 'block';
      waBtn.lastChild.textContent = ' Tanya via WhatsApp';
    } else {
      waBtn.disabled = true;
      waBtn.onclick = null;
      waBtn.querySelector('svg').style.display = 'none';
      waBtn.lastChild.textContent = ' Stok sedang habis';
    }

    const overlay = document.getElementById('productModal');
    overlay.classList.add('open');
    requestAnimationFrame(()=> overlay.classList.add('show'));
    document.body.style.overflow = 'hidden';
  }

  function closeProductModal(){
    const overlay = document.getElementById('productModal');
    overlay.classList.remove('show');
    document.body.style.overflow = '';
    setTimeout(()=> overlay.classList.remove('open'), 250);
  }

  document.addEventListener('keydown', e=>{
    if(e.key === 'Escape') closeProductModal();
  });

  // === Fix: menu toggle (hamburger) ===
  const navToggleBtn = document.querySelector('.nav-toggle');
  const navLinksEl = document.querySelector('.nav-links');
  if(navToggleBtn && navLinksEl){
    navToggleBtn.addEventListener('click', e=>{
      e.stopPropagation();
      navLinksEl.classList.toggle('is-open');
    });
    navLinksEl.querySelectorAll('a').forEach(a=>{
      a.addEventListener('click', ()=> navLinksEl.classList.remove('is-open'));
    });
    document.addEventListener('click', e=>{
      if(navLinksEl.classList.contains('is-open') && !navLinksEl.contains(e.target) && e.target !== navToggleBtn){
        navLinksEl.classList.remove('is-open');
      }
    });
  }

  // === Fix: kolom pencarian produk (filter tampil/sembunyi + highlight) ===
  const productSearchInput = document.getElementById('productSearch');
  if(productSearchInput){
    let searchDebounce;
    const clearHighlight = ()=>{
      document.querySelectorAll('.prod-card.search-match').forEach(c=> c.classList.remove('search-match'));
    };
    const showAll = ()=>{
      document.querySelectorAll('.prod-card[data-pid]').forEach(card=>{
        card.style.display = '';
      });
    };
    const doSearch = ()=>{
      const q = productSearchInput.value.trim().toLowerCase();
      clearHighlight();
      const cards = Array.from(document.querySelectorAll('.prod-card[data-pid]'));
      if(q === ''){
        showAll();
        return;
      }
      let firstMatch = null;
      cards.forEach(card=>{
        const nameEl = card.querySelector('h4');
        const name = nameEl ? nameEl.textContent.toLowerCase() : '';
        const isMatch = name.includes(q);
        card.style.display = isMatch ? '' : 'none';
        if(isMatch && !firstMatch) firstMatch = card;
      });
      if(firstMatch){
        firstMatch.classList.add('search-match');
        firstMatch.scrollIntoView({behavior:'smooth', block:'center'});
      }
    };
    productSearchInput.addEventListener('input', ()=>{
      clearTimeout(searchDebounce);
      searchDebounce = setTimeout(doSearch, 350);
    });
    productSearchInput.addEventListener('keydown', e=>{
      if(e.key === 'Enter'){
        clearTimeout(searchDebounce);
        doSearch();
      }
    });
  }
